import sys; sys.path.insert(0,'/home/claude/scripts')
from facts_lib import save
N="تعليمات اتحاد طلبة جامعة العلوم والتكنولوجيا الأردنية"
F=[]
def r(i,c,a,q1,q2,q3): F.append(("rule",[i],c,a,q1,q2,q3))
r(1,"المادة 1","تصدر تعليمات اتحاد طلبة الجامعة بموجب المادة (36) من قانون الجامعات الأردنية رقم (18) لسنة 2018، ويعمل بها ابتداءً من تاريخ إقرارها.","بموجب أي قانون تصدر تعليمات اتحاد طلبة الجامعة ومتى يعمل بها؟","ما سند إصدار تعليمات اتحاد الطلبة وتاريخ العمل بها؟","على أي قانون بتستند تعليمات اتحاد الطلبة؟")
r(1,"المادة 2 (تعريفات)","الهيئة الإدارية هي الهيئة التنفيذية المنتخبة من مجلس الاتحاد وتدير شؤونه وتنفذ قراراته. واللجنة العليا هي لجنة يشكلها رئيس الجامعة لإدارة الانتخابات. والانتخاب ورقي و/أو إلكتروني يصدر الرئيس أسسه وإجراءاته بناءً على توصية اللجنة العليا للانتخاب. والأغلبية المطلقة هي ما زاد عن 50%.","ما المقصود بالهيئة الإدارية واللجنة العليا والأغلبية المطلقة في تعليمات اتحاد الطلبة؟","هل الانتخاب في اتحاد الطلبة ورقي أم إلكتروني ومن يصدر أسسه؟","شو معنى الأغلبية المطلقة بتعليمات اتحاد الطلبة؟")
r(1,"المادة 2 (القوائم)","القائمة العامة هي القائمة المشكلة من مترشحين من مختلف الكليات على مستوى الجامعة وتحدد اللجنة العليا أعداد المترشحين بها. والقائمة المحلية هي القائمة على مستوى الكلية أو القسم، وتشكل في الكلية أو القسم الذي تزيد مقاعده عن مقعد واحد. ونسبة الحسم (العتبة) هي الحد الأدنى من أصوات المقترعين الذي يجب أن تحصل عليه القائمة للتنافس على مقعد أو أكثر.","ما الفرق بين القائمة العامة والقائمة المحلية في انتخابات اتحاد الطلبة؟","متى تشكل القائمة المحلية وما هي نسبة الحسم؟","شو هي العتبة بانتخابات اتحاد الطلبة؟")
r(1,"المادة 3","يشكل اتحاد الطلبة تنظيماً طلابياً له شخصية اعتبارية ومخصصات مالية تقرها الجامعة ومقره داخل الحرم الجامعي/عمادة شؤون الطلبة، ويمارس مهامه من خلال: مجلس الاتحاد، والهيئة الإدارية، ولجان الكليات والأقسام، ولجان النشاط.","ما الهيئات التي يمارس اتحاد الطلبة مهامه من خلالها؟","أين مقر اتحاد الطلبة وهل له شخصية اعتبارية؟","شو هي هيئات اتحاد الطلبة؟")
r(1,"المادة 4 (1-5)","من أهداف الاتحاد: المشاركة في بناء الشخصية الطلابية المتكاملة الواعية لقضايا أمتها وتعزز الانتماء للجامعة والوطن والأمة؛ وتمثيل الطلبة لدى الجامعة وتبني قضاياهم لتحقيق مصالحهم وفق تشريعات الجامعة؛ وتوثيق الصلة بين الطلبة والعاملين في الجامعة؛ والمشاركة في نشاطات الجامعة الثقافية والعلمية والاجتماعية والرياضية والنشاطات الخارجية مع الجامعات الأردنية؛ والعمل على وحدة الصف وتوثيق الوحدة الوطنية ونبذ النعرات الجهوية والطائفية والإقليمية والعنصرية.","ما أهداف اتحاد طلبة الجامعة؟","هل من أهداف الاتحاد تمثيل الطلبة لدى الجامعة؟","شو هدف اتحاد الطلبة بالنسبة لقضايا الطلاب؟")
r(1,"المادة 4 (6-9)","ومن أهداف الاتحاد: تنمية روح الحوار واحترام الرأي والرأي الآخر وتعزيز التعاون والعمل الجماعي بما ينسجم والتوجيهات والمبادرات الملكية ومحاور الأوراق النقاشية؛ والتفاعل البناء مع المجتمع المحلي ومؤسساته الرسمية؛ وتوثيق الصلات مع المنظمات الطلابية العربية والإسلامية والعالمية؛ ومناصرة قضايا الأمة العربية والإسلامية.","هل من أهداف اتحاد الطلبة توثيق الصلات مع المنظمات الطلابية العربية والإسلامية؟","ما الأهداف المتعلقة بالحوار والمجتمع المحلي في تعليمات الاتحاد؟","اتحاد الطلبة بيناصر قضايا الأمة؟")
r(1,"المادة 5","تناط عملية الانتخابات باللجنة العليا برئاسة العميد، وتتألف من ثلاثة ممثلين عن الاتحاد تسميهم الهيئة الإدارية بشرط عدم ترشيحهم (وإن تعذر لأكثر من خمسة أيام من إعلام رئيس الاتحاد يسميهم مدير دائرة الأنشطة والمبادرات الطلابية)، وثلاثة ممثلين عن عمادة شؤون الطلبة من بينهم رئيس اللجنة ومدير دائرة الأنشطة كأمين سر. وتكون اجتماعاتها قانونية بحضور 50% أو أكثر من أعضائها وقراراتها بالأغلبية، وإذا تساوت الأصوات يكون صوت الرئيس مرجحاً.","كيف تتشكل اللجنة العليا للانتخابات في اتحاد الطلبة وما نصاب اجتماعها؟","من يسمي ممثلي الاتحاد في اللجنة العليا وما شرطهم؟","شو النصاب القانوني للجنة العليا للانتخابات؟")
r(1,"المادة 6 (أ-1 إلى أ-3)","من مهام اللجنة العليا: تشكيل لجان فرعية للاقتراع والفرز في كل دائرة انتخابية من ممثل عن الطلبة يعينه العميد، وممثل عن عمادة شؤون الطلبة كأمين سر، وعضو هيئة تدريسية من القسم المعني بتنسيب عميد الكلية مقرراً؛ ولها تعيين ممثلين إضافيين عند الحاجة؛ واعتماد مراكز الاقتراع والفرز. وينتهي عملها بعد إجراء انتخابات الهيئة الإدارية والبت في الطعون.","كيف تتشكل لجان الاقتراع والفرز الفرعية في الدوائر الانتخابية؟","متى ينتهي عمل اللجنة العليا للانتخابات؟","مين بكون مقرر لجنة الاقتراع الفرعية؟")
r(1,"المادة 6 (أ-4 إلى أ-6)","تشكل اللجنة العليا لجنة فنية لإدارة انتخابات الهيئة الإدارية من رئيس اللجنة العليا أو من ينوب عنه ومدير دائرة الأنشطة والمبادرات الطلابية ونواب أو مساعدي عميد شؤون الطلبة، وتقوم بإدارة وتنظيم الاقتراع والفرز لانتخابات الهيئة الإدارية. وللجنة العليا مراجعة شروط الترشيح واختيار الطريقة المناسبة لإجراء الانتخابات وتحديد موعدها.","من يدير انتخابات الهيئة الإدارية لمجلس اتحاد الطلبة؟","ما تركيبة اللجنة الفنية في انتخابات الهيئة الإدارية؟","مين بحدد موعد وطريقة الانتخابات؟")
r(1,"المادة 9","يحق للهيئة الإدارية تقديم شكوى بحق أي طالب إلى عميد شؤون الطلبة في حالة مخالفته لتعليمات الاتحاد أو ارتكابه ما يسيء إلى سمعة الاتحاد لاتخاذ الإجراء المناسب.","هل يحق للهيئة الإدارية تقديم شكوى بحق طالب أساء لسمعة الاتحاد؟","لمن تقدم الهيئة الإدارية الشكوى على الطالب المخالف؟","إذا طالب أساء لسمعة الاتحاد، مين بشتكي عليه؟")
r(1,"المادة 10 (2، 4)","يشترط للترشح أن يكون الطالب منتظماً في دراسته عند تقديم طلب الترشيح وطيلة عضويته (بتسجيل الحد الأدنى من الساعات المعتمدة باستثناء الصيفي). وإذا وجد في سجله الأكاديمي (غير مكتمل) يعتمد معدله في الفصل السابق بوثيقة من وحدة القبول والتسجيل على أن يصوب وضعه قبل إعلان أسماء المترشحين النهائي.","ما معنى الانتظام في الدراسة كشرط للترشح لمجلس الاتحاد؟","ماذا يحدث للمترشح الذي في سجله مساق غير مكتمل؟","عندي غير مكتمل وبدي أترشح لاتحاد الطلبة، شو بصير؟")
r(1,"المادة 10 (9) مصادرة التأمين","يدفع المترشح في القائمة المحلية تأميناً مستردّاً قدره 50 ديناراً، والمترشح عن القائمة العامة 100 دينار، ويحق للجنة العليا مصادرة مبلغ التأمين في حال مخالفة المرشح أياً من تعليمات وشروط الترشيح والانتخابات.","كم مبلغ التأمين المسترد للمترشح في القائمة المحلية والعامة؟","متى يحق للجنة العليا مصادرة مبلغ التأمين؟","كم لازم أدفع تأمين لأترشح عن القائمة العامة؟")
r(1,"المادة 11 (ب، ج)","في حال تعذر إجراء الانتخابات في موعدها نتيجة ظروف استثنائية يقدرها الرئيس يستمر مجلس الاتحاد والهيئة الإدارية في أداء مهامهم حتى زوال الظروف وانتخاب مجلس وهيئة جديدين. ويغلق المقر الرئيسي للاتحاد والمقار الفرعية طيلة فترة الإعداد للانتخابات ولمدة 21 يوماً من الموعد الذي تحدده اللجنة العليا تحقيقاً للعدالة بين الطلبة.","ماذا يحدث إذا تعذر إجراء انتخابات اتحاد الطلبة في موعدها؟","لماذا وكم مدة إغلاق مقار الاتحاد قبل الانتخابات؟","متى بتسكروا مقر الاتحاد قبل الانتخابات؟")
r(1,"المادة 12 (أ، ب-2)","تقسم الجامعة إلى دوائر انتخابية محلية ودائرة انتخابية عامة واحدة على مستوى الجامعة تحددها اللجنة العليا وتخصص عدد مقاعدها. وإذا أغلق باب الترشيح ولم يكتمل العدد المطلوب من المرشحين أو لم تنطبق عليهم الشروط، ينسب عميد الكلية المعنية بأسماء الطلبة المشاركين بالأنشطة والمتميزين فيها ممن تنطبق عليهم شروط الترشح ليكتمل العدد.","كيف يكتمل عدد المرشحين إذا لم يترشح العدد المطلوب في الكلية؟","كيف تقسم الجامعة إلى دوائر انتخابية لاتحاد الطلبة؟","ما الحل لو ما ترشح عدد كافي بالكلية؟")
r(1,"المادة 12 (ج)","تشكل القائمة العامة (على مستوى الجامعة) بحيث تضم طالبة واحدة على الأقل ضمن المترشحين الثلاثة الأوائل، ومترشحين موزعين على دوائر انتخابية محلية مختلفة، وعدداً من الطالبين للترشح لا يقل عن نصف عدد المقاعد المخصصة لها، وبتمثيل لا يقل عن 3 كليات مختلفة.","ما شروط تشكيل القائمة العامة في انتخابات اتحاد الطلبة؟","هل يجب أن تضم القائمة العامة طالبة؟ وكم كلية تمثل؟","شو شروط القائمة العامة؟")
r(1,"المادة 13 (ب، ج)","ينتخب الفائزون في الكلية من بينهم رئيس لجنة الكلية بالتصويت، فإذا كان ممثلو الكلية 3 أو أكثر فالحاصل على أعلى الأصوات هو الرئيس، وإذا كانوا أقل من 3 فالحاصل على أعلى الأصوات رئيس اللجنة، وعند التساوي تجري القرعة. والحد الأدنى لكل قسم عضو واحد، ويجوز للجنة العليا دمج أي قسم بقسم آخر في نفس الكلية إذا كان طلبته لا يزيدون عن 100 طالب.","كيف ينتخب رئيس لجنة الكلية في اتحاد الطلبة؟","متى يجوز دمج قسم بقسم آخر في الانتخابات؟","كم عدد الطلبة الذي يسمح بدمج القسم بقسم ثاني؟")
r(1,"المادة 14 (ب-ه)","تعلن أسماء المرشحين قبل خمسة أيام دراسية من موعد الانتخابات، وتبدأ الدعاية الانتخابية بعد إعلانها، ويتعهد المرشحون خطياً بعدم وضع الإعلانات الدعائية إلا في الأماكن المخصصة خارج مباني الكليات وإلا تعرضوا للمسؤولية التأديبية. وفي حال انسحاب المرشح أثناء فترة الترشح لا يجوز إعادة ترشيحه.","متى تعلن أسماء المرشحين وأين يسمح بوضع الإعلانات الدعائية؟","هل يجوز إعادة ترشيح من انسحب أثناء فترة الترشح؟","متى بتبدأ الدعاية الانتخابية؟")
r(1,"المادة 15 (ب، ج)","يحق استخدام اسم القائمة ورمزها في أي دائرة انتخابية بناءً على اتفاق خطي بين مفوضي القوائم وموافقة رئيس اللجنة العليا. ويشترط في مفوض القائمة أن يكون طالباً على مقعد الدرس، وتشمل مهامه تقديم أسماء المرشحين واسم القائمة ورمزها بالترتيب حسب النموذج، والالتزام بالتعليمات، والاعتراض على النتائج الأولية للجنة العليا مشفوعاً بالأدلة، وتدقيق أسماء المرشحين، ومعالجة أي اختلال بالبيانات، ويتحمل المسؤولية القانونية عن أي مخالفة للقائمة ولو على وسائل التواصل الاجتماعي.","ما مهام مفوض القائمة الانتخابية وما شرطه؟","هل يجوز استخدام اسم القائمة ورمزها في أكثر من دائرة؟","شو مسؤولية مفوض القائمة؟")
r(1,"المادة 15 (د، هـ)","إذا قررت اللجنة العليا رفض طلب الترشح فعليها بيان أسباب الرفض، ويبلغ رئيس اللجنة أو من يفوضه طالب الترشح بالقرار. ويتخذ رئيس اللجنة الإجراءات اللازمة لعرض أسماء القوائم والمترشحين المقبولين على الموقع الإلكتروني للجامعة وفي كلياتهم.","هل يجب على اللجنة العليا بيان أسباب رفض طلب الترشح؟","أين تعرض أسماء القوائم والمترشحين المقبولين؟","رفضوا ترشيحي، لازم يعطوني السبب؟")
r(1,"المادة 16 (ب، د)","على اللجنة العليا الإعلان عن سحب اسم أي مترشح أو قائمة محلية بأي وسيلة تراها مناسبة. ولا يؤثر خروج أي عضو مترشح في القائمة العامة لأي سبب على بقاء القائمة بعد الموافقة على ترشحها، ويفقد ترتيبه فيها مع إعادة ترتيب المترشحين الباقين حسب التسلسل من مفوض القائمة.","ماذا يحدث للقائمة العامة إذا خرج أحد مترشحيها؟","كيف يعاد ترتيب المترشحين في القائمة العامة عند خروج أحدهم؟","إذا انسحب واحد من القائمة العامة، القائمة بتسقط؟")
r(1,"المادة 18","تحدد اللجنة العليا أعداد الطلبة المسجلين في كل قسم وعدد ممثليهم حسب القوائم الرسمية من وحدة القبول والتسجيل، ولا تشمل الطلبة في البرامج الخاصة والعرب والأجانب وذوي الإعاقة. ويتم الانتخاب باستعمال هوية جامعية واضحة المعالم أو (هوية الأحوال المدنية أو رخصة القيادة أو جواز السفر مرفقة بإثبات طالب من وحدة القبول والتسجيل) ولا يجوز اعتماد أي طريقة أخرى.","ما الوثائق المقبولة للتصويت في انتخابات اتحاد الطلبة؟","من يدخل في أعداد الطلبة لتحديد عدد الممثلين في كل قسم؟","بأي هوية بقدر أنتخب؟")
r(1,"المادة 19 و20 (1، 2)","يحق للمرشحين وللقوائم تقديم أسماء مندوبيهم لكل مركز اقتراع إلى اللجنة الفرعية بما لا يزيد عن مندوب واحد (طالب) لكل مرشح وقائمة. وتحرر لجنة الانتخاب الفرعية محاضر الاقتراع والفرز ويوقعها أعضاؤها، وتحل الإشكالات بقرار أغلبية أعضائها المطلقة، وعند تساوي أكثر من مرشح في الأصوات التي تحدد الفائز الأخير تجرى القرعة وتعتبر نتيجتها قطعية.","كم مندوباً يحق لكل مرشح وقائمة تقديمه لمركز الاقتراع؟","كيف تحسم اللجنة الفرعية تساوي الأصوات بين مرشحين؟","مين بحل الإشكالات بمراكز الاقتراع؟")
r(1,"المادة 20 (3، 4)","تعتبر نماذج الاقتراع باطلة إذا كانت غير موقعة ومختومة بخاتم اللجنة الفرعية. وإذا حصل زيادة أو نقصان في عدد نماذج الاقتراع داخل الصندوق عن أعداد المقترعين يحال الأمر للجنة العليا للبت فيه ويعتبر قرارها قطعياً.","متى تعتبر نماذج الاقتراع باطلة؟","ماذا يحدث إذا اختلف عدد الأوراق في الصندوق عن عدد المقترعين؟","ورقة الاقتراع بدون ختم بتنحسب؟")
r(1,"المادة 21 (2-6)","تحصل كل قائمة محلية تجاوزت العتبة على مقاعد بنسبة أصواتها من مجموع أصوات القوائم التي تجاوزتها، ويحدد الفائزون على أساس أعلى الأصوات للمترشحين في القائمة. وإذا تساوت نسبة الأصوات بين قائمتين أو مترشحين يحتكم إلى العدد المطلق للأصوات، وإذا تساوى يجري مقرر لجنة الانتخاب الفرعية القرعة وينظم محضر بذلك. ويعلن المقرر نتيجة الفرز في مركز الاقتراع.","كيف توزع المقاعد على القوائم المحلية التي تجاوزت نسبة الحسم؟","كيف يتم الفصل عند تساوي الأصوات بين قائمتين أو مترشحين؟","شو بصير لو تساوت الأصوات بين مرشحين؟")
r(1,"المادة 22","يحدد الفائزون بمقاعد الدائرة العامة بأن تتجاوز القائمة العامة عتبة 5% من المقترعين، وتحصل كل قائمة على مقاعد بنسبة أصواتها من مجموع أصوات القوائم التي تجاوزتها، وإذا لم تصل القوائم العتبة تخفضها اللجنة العليا بمقدار 1% على التوالي. ويحدد الفائزون على أساس الترتيب الوارد من مفوض القائمة العامة، وعند التساوي يحتكم إلى العدد المطلق للأصوات ثم القرعة.","كيف يحدد الفائزون بمقاعد الدائرة الانتخابية العامة؟","على أي أساس يحدد الفائزون داخل القائمة العامة؟","كيف بتتوزع مقاعد القائمة العامة؟")
r(1,"المادة 23","تملأ اللجنة العليا مقعد الكوتا من كل كلية أو معهد في الجامعة بتنسيب من عمداء الكليات، وتعين طالبين من ذوي الإعاقة كأعضاء في مجلس الاتحاد، وتعين طلبة من العرب والأجانب أعضاء في المجلس، وطالباً من الطلبة العرب والأجانب من كلية الدراسات العليا بتنسيب من عميد كلية الدراسات العليا.","من يعين ذوي الإعاقة والطلبة العرب والأجانب في مجلس اتحاد الطلبة؟","كم طالباً من ذوي الإعاقة يعين في مجلس الاتحاد؟","كيف يتمثل الطلبة العرب والأجانب في الاتحاد؟")
r(1,"المادة 24","يحق لأي مرشح أو مفوض قائمة تقديم الطعن في نتائج الانتخابات في دائرته لرئيس اللجنة العليا خلال مدة لا تتجاوز ثلاثة أيام دراسية من تاريخ انتخاب الهيئة الإدارية الجديدة، وتحقق اللجنة وتبت في الطعن بحضور صاحبه، ويكون قرارها نهائياً وغير قابل للطعن.","خلال كم يوماً يقدم الطعن في نتائج انتخابات الاتحاد وهل قرار اللجنة نهائي؟","من يحق له الطعن في نتائج الانتخابات؟","بدي أطعن بنتيجة الانتخابات، كم عندي وقت؟")
r(1,"المادة 25 (3)","من صلاحيات مجلس الاتحاد: انتخاب الهيئة الإدارية بالاقتراع السري المباشر، ورسم السياسة العامة للاتحاد والمصادقة على خطة عمله وموازنته، وإنهاء عضوية أي عضو من الهيئة الإدارية إذا ارتكب عملاً محظوراً أو مخالفة تخل بالشرف والسمعة وأدين بها، والبت في استقالة أي عضو، ومناقشة التقارير المالية والإدارية للهيئة الإدارية وخطط عملها وإقرارها.","ما صلاحيات مجلس اتحاد الطلبة؟","من يقر خطة الاتحاد وموازنته؟","مين بنتخب الهيئة الإدارية؟")
r(1,"المادة 26 (أ، ب، ج)","يجتمع مجلس الاتحاد اجتماعاً عادياً في بداية كل فصل وآخر في نهاية مدته، واجتماعاً لمناقشة الموازنة والخطة المقدمتين من الهيئة الإدارية خلال شهر من انتخابها. ويجوز دعوته لاجتماع استثنائي بموافقة عمادة شؤون الطلبة بدعوة من الهيئة الإدارية أو بطلب خطي من ثلث الأعضاء على الأقل (وعلى الهيئة دعوته خلال أسبوع). وتعلن الهيئة عن الاجتماع قبل ثلاثة أيام دراسية أثناء الدراسة وخمسة أيام أثناء العطل.","كم اجتماعاً عادياً يعقده مجلس الاتحاد وكيف يدعى لاجتماع استثنائي؟","قبل كم يوم يعلن عن اجتماع مجلس الاتحاد؟","كيف بنطلب اجتماع استثنائي لمجلس الاتحاد؟")
r(1,"المادة 26 (د، هـ)","يترأس اجتماع مجلس الاتحاد رئيس الاتحاد، وعند غيابه نائبه، وعند غيابهما أكبر أعضاء الهيئة الإدارية الحاضرين سناً. ويعتبر الاجتماع قانونياً بحضور الأغلبية المطلقة من أعضائه وأحد أعضاء الهيئة الإدارية على الأقل، وإذا لم يكتمل النصاب بعد ثلث ساعة يحدد رئيس الاتحاد موعد الاجتماع القادم خلال مدة لا تتجاوز أسبوعاً ولا تقل عن يومين، ويعتبر الاجتماع المؤجل قانونياً مهما بلغ عدد الحضور.","ما النصاب القانوني لاجتماع مجلس الاتحاد وماذا يحدث إذا لم يكتمل؟","من يترأس اجتماع المجلس عند غياب رئيس الاتحاد ونائبه؟","شو بصير لو ما اكتمل النصاب بمجلس الاتحاد؟")
r(1,"المادة 26 (ز)","إذا خلا منصب عضو في المجلس لأي سبب ينسب عميد الكلية المعنية بالبديل من الطلبة المشاركين بالأنشطة أو الهيئات الطلابية، وينطبق ذلك على الفائزين بالتزكية والطالبات المعينات، ويبقى المقعد شاغراً خلاف ذلك. وإذا قل أعضاء مجلس الاتحاد عن النصف يحل المجلس وتجرى انتخابات جديدة مباشرة.","كيف يملأ مقعد العضو الشاغر في مجلس الاتحاد وماذا لو قل الأعضاء عن النصف؟","من ينسب بديل العضو الذي خلا مقعده؟","إذا قل أعضاء مجلس الاتحاد عن النصف، شو بصير؟")
r(1,"المادة 26 (ط، ي)","إذا لم يحصل المرشحون لرئاسة الاتحاد على الأغلبية المطلقة من أصوات الأعضاء الحاضرين تجرى جولة ثانية بين المرشحين الحاصلين على أعلى الأصوات، ويفوز من يحصل على أعلى الأصوات، وإذا لم تحسم النتيجة تجرى القرعة. ويتخذ المجلس قراراته بالأغلبية المطلقة من الحاضرين، وبأغلبية الثلثين في حل المجلس وفصل عضو والبت في التظلم وحجب الثقة عن الهيئة الإدارية أو أحد أعضائها، بطلب خطي من ثلث الأعضاء وجلسة خاصة يعلن عنها قبل أسبوع.","ما القرارات التي تتطلب أغلبية الثلثين في مجلس الاتحاد؟","ماذا يحدث إذا لم يحصل أي مرشح لرئاسة الاتحاد على الأغلبية المطلقة؟","كيف بنحجب الثقة عن الهيئة الإدارية؟")
r(1,"المادة 27","تنتخب الهيئة الإدارية بالاقتراع السري المباشر من بين أعضائها رئيساً ونائباً للرئيس وأميناً للسر وأميناً للصندوق. ويؤدي رئيس وأعضاء المجلس القسم أمام رئيس الجامعة أو من ينوبه في موعد أقصاه أسبوع من انتخاب المجلس قبل البدء بانتخابات الهيئة الإدارية، ويؤدي رئيس الاتحاد وأعضاء الهيئة الإدارية القسم أمام رئيس الجامعة أو من ينوب عنه خلال أسبوع من انتخاب الهيئة الإدارية.","أمام من ومتى يؤدي رئيس وأعضاء مجلس الاتحاد القسم؟","ما المناصب التي تنتخبها الهيئة الإدارية من بين أعضائها؟","خلال كم يوم بنحلف اليمين بعد انتخاب الهيئة الإدارية؟")
r(1,"المادة 31 (أ-5، ب)","يفقد عضو مجلس الاتحاد عضويته عند غيابه ثلاث مرات متتالية أو خمس جلسات متفرقة دون عذر يقبله المجلس، ولا يحق له العودة إلى العضوية بعد زوال السبب في الدورة نفسها. ويبلغ العضو بفقدان العضوية بأي طريقة يختارها العميد.","كم غياباً يفقد به عضو مجلس الاتحاد عضويته؟","هل يحق للعضو العودة بعد فقدان العضوية في نفس الدورة؟","غبت ثلاث جلسات، بخسر عضويتي؟")
r(1,"المادة 33","إذا خالف عضو مجلس الاتحاد التعليمات توقع عليه بعد التحقيق معه من المجلس وبموافقة العميد إحدى العقوبات: التنبيه أو الإنذار (بأغلبية الهيئة الإدارية)، أو تجميد العضوية أو الفصل من العضوية (بأغلبية ثلثي أعضاء الهيئة الإدارية). ويبلغ العضو بالقرار خطياً مع الأسباب خلال أسبوعين، وله التظلم خطياً عن طريق أمين سر المجلس خلال أسبوع من الإبلاغ، ويبت المجلس في التظلم خلال أسبوعين ويعد قراره قطعياً.","ما العقوبات التي توقع على عضو مجلس الاتحاد المخالف وبأي أغلبية؟","خلال كم يوماً يحق للعضو المعاقب التظلم وخلال كم يبت المجلس؟","انعاقبت من الاتحاد، كيف بتظلم؟")
r(1,"المادة 34 (أ)","من مهام الهيئة الإدارية: تنفيذ قرارات المجلس، وإعداد موازنة الاتحاد وتنسيبها للمجلس، ووضع خطة عمل تترجم الأهداف بنشاطات محددة، وتبني القضايا الطلابية واقتراح حلولها، ودعوة المجلس للاجتماع، والنظر في الاقتراحات والتقارير، وتقديم التقارير المالية والإدارية، والإشراف على لجان الدوائر المنتخبة ومراقبة أعمالها واجتماعات الهيئة العامة، والنظر في المخالفات وإصدار العقوبة اللازمة.","ما مهام وصلاحيات الهيئة الإدارية لاتحاد الطلبة؟","هل تشرف الهيئة الإدارية على لجان الدوائر المنتخبة؟","شو بتعمل الهيئة الإدارية؟")
r(1,"المادة 34 (ب)","يجوز القيام بأية نشاطات لا منهجية خارج الخطة بموافقة ثلثي أعضاء المجلس بتنسيب من العميد وموافقة الرئيس.","كيف يمكن القيام بنشاط لا منهجي خارج خطة الاتحاد؟","من يوافق على نشاط خارج خطة اتحاد الطلبة؟","بدنا نعمل نشاط مش بالخطة، شو بلزم؟")
r(1,"المادة 37","يعين عميد شؤون الطلبة أحد العاملين مندوباً عن عمادته في الهيئة الإدارية، يحضر اجتماعاتها ويشارك في المناقشات دون حق التصويت، ويحق له رفض القرار إذا كان مخالفاً للتشريعات المعمول بها في الجامعة.","من يمثل عمادة شؤون الطلبة في اجتماعات الهيئة الإدارية وهل له حق التصويت؟","هل لمندوب العميد رفض قرار للهيئة الإدارية؟","مين مندوب العمادة بالهيئة الإدارية؟")
r(1,"المادة 38 و39","إذا شغر مقعد في الدائرة المحلية يشغله المترشح الذي يلي الفائز في القائمة ذاتها، وإذا تعذر فمن مترشحي القائمة التالية في النسبة بحسب أعلى الأصوات. وإذا شغر مقعد في الدائرة العامة يشغله المترشح التالي في القائمة ذاتها، وإن تعذر فمن القائمة التي تليها، وعند تساوي القوائم يحتكم إلى العدد المطلق ثم القرعة من رئيس اللجنة العليا. ويشغل المقعد الشاغر لذوي الإعاقة أو الطلبة العرب والأجانب والدراسات العليا بحسب المادة 26 (ز) وإلا يعين العميد بديلاً، وتملأ المقاعد الكسرية بطريقة الباقي الأعلى.","كيف يملأ المقعد الشاغر في الدائرة المحلية أو العامة بمجلس الاتحاد؟","ما طريقة ملء المقاعد عند تعذر الأرقام الصحيحة؟","شو بصير لو شغر مقعد طالبة؟")
r(1,"المادة 40 و59","يجوز لمجلس الاتحاد حل نفسه بموافقة ثلثي أعضائه على الأقل، وفي هذه الحالة يدعو رئيس الجامعة لإجراء انتخابات استثنائية خلال شهر من تاريخ القرار. ولمجلس الجامعة بناءً على تنسيب الرئيس حل مجلس الاتحاد استناداً إلى ظروف استثنائية يقدرها مجلس الجامعة.","من يملك حل مجلس اتحاد الطلبة؟","خلال كم من الوقت تجرى الانتخابات الاستثنائية بعد حل المجلس نفسه؟","بالظروف الاستثنائية، مين بقدر يحل مجلس الاتحاد؟")
r(1,"المادة 41 (1، 2)","يتولى رئيس الاتحاد رئاسة اجتماعات الهيئة الإدارية والتوقيع على قراراتها وعلى أوامر صرف سلفة النفقات بعد قرارها وتمثيل المجلس أمام الجهات الرسمية والطلابية والشعبية بأخذ الموافقة رسمياً والدعوة للاجتماعات، واستلام ختم الاتحاد وحفظه ويغرم ضعفي قيمته عند فقدانه. ونائب الرئيس يقوم بمهامه أثناء غيابه أو توكيله، وبما يسنده إليه الرئيس بموافقة العميد.","ما مهام رئيس الاتحاد ونائبه؟","كم يغرم رئيس الاتحاد إذا فقد ختم الاتحاد؟","ضيّعت ختم الاتحاد، شو العقوبة؟")
r(1,"المادة 41 (3، 4)","يتولى أمين السر توجيه الدعوة لاجتماعات الهيئة ومجلس الاتحاد وتحضير جداول الأعمال والتوقيع على المحاضر وتدوين وقائع الجلسات ومتابعة تنفيذ القرارات واستلام المراسلات وحفظها. ويصرف أمين الصندوق سلفة النفقات باسمه ويسددها حسب الأصول، ويعد التقارير المالية (ولا يصرف دعم أي نشاط عند عدم الالتزام بذلك)، ويحتفظ بنسخة مختومة من الدفاتر والمستندات المالية في مقر الاتحاد.","ما مهام أمين السر وأمين الصندوق في الاتحاد؟","ماذا يحتفظ به أمين الصندوق في مقر الاتحاد؟","شو دور أمين الصندوق؟")
r(1,"المادة 42","للهيئة الإدارية صلاحية توكيل أو تفويض أية مهمة محددة لأي من أعضائها ومحاسبة أي عضو شريطة تقديم الأسباب والمبررات لعمادة شؤون الطلبة، ويحق للعميد تحويل أي عضو يتعمد تأخير العمل أو عدم القيام بمهامه إلى لجان تأديب الطلبة المختصة.","هل يحق للهيئة الإدارية محاسبة أحد أعضائها وماذا يملك العميد؟","من يحول العضو المقصر إلى لجان التأديب؟","عضو مقصر بالهيئة الإدارية، شو بصير فيه؟")
r(1,"المادة 43 (أ، ب)","يشكل المجلس لجانه الدائمة (الأنشطة، التعليم، الصحة والبيئة، العمل التطوعي والتنمية الاجتماعية، السياحة والتراث والآثار، الحريات وحقوق الطلبة، الطالبات، المالية والاقتصادية، الإعلام والتوجيه الوطني، الأقصى، قضايا الطلبة، الدعوية والمصليات، الريادة والإبداع، المبادرات، العلمية) على ألا يقل عدد أعضاء أي لجنة عن ثلاثة. وللهيئة الإدارية تشكيل لجان مؤقتة بموافقة العميد. وتقدم كل لجنة تقريراً شهرياً مفصلاً بنشاطاتها ومصروفاتها وإيراداتها وخطة الشهر التالي، ولا يسمح لها بتنفيذ الأنشطة عند عدم الالتزام.","ما اللجان الدائمة لمجلس اتحاد الطلبة وكم أقل عدد لأعضائها؟","ما التقرير الذي تقدمه كل لجنة ومتى يمنع تنفيذ نشاطها؟","كم عضو لازم بلجنة الاتحاد؟")
r(1,"المادة 43 (د-ز)","ترفع كل لجنة توصياتها للهيئة الإدارية ويشترط موافقتها على أي نشاط أو صرف مبالغ قبل إجرائه. ويعتبر اجتماع اللجنة قانونياً بالإعلان عنه قبل يومين على الأقل وحضور الأغلبية المطلقة، وإذا لم يكتمل النصاب يؤجل يومين على الأقل ويكون قانونياً بعد ذلك. وتتخذ القرارات بالأغلبية المطلقة وعند التساوي يرجح صوت الرئيس. وللمجلس والهيئة الإدارية صلاحية حل أي لجنة أو فصل أي عضو بالأغلبية المطلقة وموافقة العميد.","ما النصاب القانوني لاجتماع لجنة في اتحاد الطلبة؟","من يملك حل لجنة أو فصل عضو منها؟","هل تحتاج اللجنة موافقة الهيئة الإدارية قبل تنفيذ نشاط؟")
r(1,"المادة 44","تتولى لجنة الكلية: وضع خطة العمل السنوية للجنة وعرضها على الهيئة الإدارية، ووضع خطة مساهمتها في برنامج عمل الهيئة، وإعداد التقرير السنوي لأنشطتها، ومتابعة النشاطات التي يقرها مجلس الاتحاد على مستوى الكلية، ودراسة قضايا طلبة الكلية واقتراح الحلول ورفعها للهيئة الإدارية، وتنفيذ قرارات الهيئة الخاصة بشؤون طلبة الكلية.","ما مهام لجنة الكلية في اتحاد الطلبة؟","هل ترفع لجنة الكلية قضايا الطلبة للهيئة الإدارية؟","شو دور لجنة الكلية؟")
r(1,"المادة 45","تسقط عضوية أي عضو في المجلس أو هيئاته أو لجانه في الأحوال: الاستقالة الخطية، الانتقال من كلية إلى أخرى أثناء العضوية، الغياب ثلاثة اجتماعات متتالية أو ستة متفرقة دون عذر مقبول، فقدان أحد شروط العضوية في المادة 10 (باستثناء شرط بقاء فصلين على التخرج)، إدانته بجناية أو جنحة مخلة بالشرف والأمانة، وترك الجامعة أو الفصل منها.","ما حالات سقوط العضوية في اتحاد الطلبة؟","هل ينتقل العضو من كلية لأخرى أثناء العضوية؟","متى بتسقط عضويتي بالاتحاد؟")
r(1,"المادة 46 و47","تتكون موارد الاتحاد المالية من منحة مالية سنوية تقدمها الجامعة، والهبات والتبرعات والمنح التي يقرها المجلس ويوافق عليها الرئيس بتنسيب العميد، وريع المهرجانات والاحتفالات والنشاطات الموافق عليها من العميد، وأية موارد أخرى يقرها المجلس ويوافق عليها مجلس العمداء. ولا يحق للهيئة صرف مبالغ في الدورة بما يزيد عن مواردها. وتودع أموال الاتحاد في مصرف داخل الحرم الجامعي بحساب جار.","ما مصادر موارد اتحاد الطلبة المالية؟","أين تودع أموال الاتحاد؟","هل يجوز للاتحاد الصرف بأكثر من موارده؟")
r(1,"المادة 48 و49","تقرر الهيئة الإدارية صرف سلفة نفقات مقدارها مائة دينار في المرة الواحدة على ألا تتجاوز ثلاثمائة دينار، يحتفظ بها أمين الصندوق لتغطية المصاريف النثرية والطارئة، ولا تصرف أية سلفة أخرى لحين سداد السلفة الممنوحة. ويقدم أمين الصندوق تقريراً شهرياً عن الوضع المالي للهيئة الإدارية يناقش في أقرب اجتماع للمجلس وترسل نسخة للعميد، ولا يحق تنفيذ أنشطة جديدة عند عدم تقديمه.","كم مقدار سلفة النفقات التي يقررها الاتحاد وما حدها الأقصى؟","ما التقرير الذي يقدمه أمين الصندوق شهرياً؟","كم السلفة النثرية بالاتحاد؟")
r(1,"المادة 50 (أ، ب)","تعد الهيئة الإدارية مشروع الموازنة وتقدمه لمجلس الاتحاد لمناقشته خلال شهر من انتخابها، ويقدم لعميد شؤون الطلبة ليرفع لرئيس الجامعة ثم لمجلس العمداء لاعتماده. ويتم الصرف بمعدل 1/6 من الموازنة ما عدا آخر شهرين من الدورة فبمعدل 1/12. والسنة المالية للاتحاد هي السنة المالية للجامعة.","كيف تعتمد موازنة الاتحاد وبأي معدل يتم الصرف منها؟","ما السنة المالية للاتحاد؟","من يعتمد موازنة اتحاد الطلبة؟")
r(1,"المادة 50 (ج)","يصرف المال من موازنة الاتحاد بقرار من الهيئة الإدارية وموافقة العميد وبتوقيع عميد شؤون الطلبة ورئيس الهيئة الإدارية وأمين صندوقها. ولا يجوز تجزئة أي مبلغ للصرف ويجب تحديد كلفة النشاط مسبقاً، وتدفع الفواتير التي تزيد عن 50 ديناراً بشيك ولا تدفع نقداً من السلفة. ولا تزيد مخصصات المطبوعات عن 20% من موازنة الاتحاد، ومخصصات أي نشاط عن 7% منها خلال الدورة، وترفق نسخة من المطبوعة أو النشاط مع الفاتورة، ويطبق النظام المالي ونظام المشتريات الموحد في الجامعة.","ما الحد الأعلى لمخصصات المطبوعات وأي نشاط من موازنة الاتحاد؟","كيف تدفع الفواتير التي تزيد عن 50 ديناراً في الاتحاد؟","من يوقع على الصرف من موازنة الاتحاد؟")
r(1,"المادة 51","توقف قرارات الصرف الصادرة من الاتحاد قبل شهر (30 يوماً) من موعد الانتخابات القادمة. وتسدد جميع المستحقات قبل انتهاء العام المالي وإلا ترصد مبالغ تعادل الالتزامات للسنة القادمة. ويدور الفائض المالي للاتحاد لصالح ميزانيته في الدورات المقبلة، ويحق للعميد إعادة الفائض إلى حساب الجامعة بكتاب رسمي على أن يخصم المبلغ المدور من حساب الدورة التالية.","متى توقف قرارات الصرف قبل الانتخابات وماذا يحدث للفائض المالي؟","هل يدور الفائض المالي للاتحاد للدورة التالية؟","قبل كم يوم من الانتخابات بنوقف الصرف؟")
r(1,"المادة 52","تقوم دائرة الأنشطة والمبادرات الطلابية بشراء اللوازم للاتحاد وفق أنظمة الجامعة بطلب من رئيس الاتحاد وأغلبية أعضاء الهيئة وموافقة العميد، وتقوم مع شعبة الهيئات الطلابية بالسكرتاريا والطباعة والتنسيق مع الدائرة المالية بالأعمال المحاسبية. وتطبع الجامعة المواد التي يرغب الاتحاد بطباعتها عبر وحدة اللوازم المركزية، وتوفر متطلبات الطعام والشراب من خلال دائرة التغذية.","من يتولى شراء اللوازم والطباعة وتوفير الطعام والشراب للاتحاد؟","ما دور دائرة الأنشطة والمبادرات الطلابية في أعمال الاتحاد المالية؟","مين بطبع مطبوعات الاتحاد؟")
r(1,"المادة 53","تدعو الهيئة الإدارية لاجتماع الهيئة العامة في نهاية كل دورة وقبل 21 يوماً على الأقل من موعد الانتخابات لمناقشة التقرير المالي والإداري، ويعلن التقرير على لوحات الإعلانات داخل الحرم ويرسل نسخة للعميد قبل أسبوع من موعد الاجتماع، ويحق للهيئة الاستعانة بمحاسب قانوني من داخل الجامعة أو مكتب خاص مرخص من خارجها.","متى تدعو الهيئة الإدارية لاجتماع الهيئة العامة ولماذا؟","هل يحق للهيئة الإدارية الاستعانة بمحاسب قانوني؟","قبل كم يوم من الانتخابات بنناقش التقرير المالي؟")
r(1,"المادة 54 و55","تعتبر الهيئة الإدارية أو اللجان الفرعية مستقيلة باستقالة الأغلبية المطلقة لأعضائها المنتخبين. وتبلغ الهيئة والمجلس قراراتهما لعميد شؤون الطلبة وتكون موافقاً عليها حكماً بعد خمسة أيام دراسية من تبليغها، إلا إذا رأى العميد أنها مخالفة لقانون الجامعة أو أنظمتها أو تعليماتها، ويتولى العميد أو من ينيبه الإشراف على تنفيذ جميع نشاطات الاتحاد.","متى تعتبر قرارات الهيئة الإدارية والمجلس موافقاً عليها حكماً؟","متى تعتبر الهيئة الإدارية مستقيلة؟","كم يوم بتصير قرارات الاتحاد موافق عليها تلقائياً؟")
r(1,"المادة 56","يمارس الاتحاد اختصاصاته إلى المدى الذي لا تتعارض فيه مع اختصاصات مجالس وإدارات الجامعة وفق قوانينها، وفي حال المخالفة يطبق على أعضاء المجلس أو الهيئة نظام تأديب الطلبة. ولا يجوز للاتحاد التعامل مع أي جهة خارج الجامعة إلا من خلال العميد، ولا الاتصال أو التنسيق قبل أخذ الموافقة.","هل يجوز للاتحاد التعامل مع جهة خارج الجامعة مباشرة؟","ما القانون المطبق على أعضاء الاتحاد المخالفين لتعليماته؟","بقدر الاتحاد يتواصل مع جهة خارجية بدون العميد؟")
r(1,"المادة 57 إلى 61","تصدر اللجنة العليا للانتخابات تعليمات الدعاية الانتخابية ويحق لها سحب ترشيح أي طالب يخالفها ووضع شروط خاصة ورسوم مالية بكل دورة. ويرافق رئيس شعبة الهيئات الطلابية وتمكين الشباب كافة نشاطات الاتحاد الداخلية والخارجية (أو من يسميه مدير دائرة الأنشطة). ويبت رئيس الجامعة في الحالات التي لم يرد بها نص، وتلغي هذه التعليمات أية تعليمات أو قرارات سابقة بهذا الخصوص.","من يبت في الحالات التي لا نص عليها في تعليمات اتحاد الطلبة؟","هل يحق للجنة العليا سحب ترشيح من يخالف تعليمات الدعاية الانتخابية؟","هل تلغي هذه التعليمات التعليمات السابقة؟")
